1	// Build script: compile the tiny LD_PRELOAD shims used by the keygen
2	// regression tests (Unix only). Intentionally invokes the system C compiler
3	// directly instead of pulling in the `cc` crate, so the offline dependency
4	// set (getrandom + libc) is unchanged.
5	use std::path::Path;
6	
7	fn main() {
8	    let target_os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
9	    // The permfail shim relies on glibc's open/open64/fstat/fstat64
10	    // interposition semantics; the randtrap shim relies on seccomp
11	    // SECCOMP_RET_TRAP plus signal-frame register access (x86_64 and
12	    // aarch64 only). Build them on Linux. On other targets the shim-backed
13	    // tests detect the missing env var and skip themselves, while the
14	    // shim-free tests still run.
15	    if target_os != "linux" {
16	        println!("cargo:warning=test shims not built for target OS {target_os}; shim-backed tests will skip");
17	        return;
18	    }
19	
20	    let out_dir = std::path::PathBuf::from(std::env::var("OUT_DIR").unwrap());
21	    let cc = std::env::var("CC").unwrap_or_else(|_| "cc".to_string());
22	
23	    build_shim(
24	        &cc,
25	        "tests/support/permfail/permfail.c",
26	        &out_dir.join("libwrapfile_permfail.so"),
27	        "WRAPFILE_PERMFAIL_SO",
28	    );
29	
30	    let target_arch = std::env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
31	    if matches!(target_arch.as_str(), "x86_64" | "aarch64") {
32	        build_shim(
33	            &cc,
34	            "tests/support/randtrap/randtrap.c",
35	            &out_dir.join("libwrapfile_randtrap.so"),
36	            "WRAPFILE_RANDTRAP_SO",
37	        );
38	    } else {
39	        println!("cargo:warning=randtrap shim not built for target arch {target_arch}; random-source tests will skip");
40	    }
41	}
42	
43	fn build_shim(cc: &str, src: &str, so_path: &Path, env_var: &str) {
44	    let status = std::process::Command::new(cc)
45	        .args(["-O0", "-g", "-fPIC", "-shared", "-Wall", "-Wextra"])
46	        .arg("-o")
47	        .arg(so_path)
48	        .arg(src)
49	        .status();
50	
51	    match status {
52	        Ok(s) if s.success() => {}
53	        Ok(s) => panic!("{src} compile failed with status {s}"),
54	        // A machine without a C compiler can still build/use wrapfile
55	        // itself; skip exporting the shim path so the shim-backed tests
56	        // print a skip notice. A compiler that ran but rejected the source
57	        // is a real error and must fail loudly (the Ok arm above).
58	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
59	            println!("cargo:warning=C compiler '{cc}' not found; {src} not built, dependent tests will skip");
60	            return;
61	        }
62	        Err(e) => panic!("failed to run C compiler while building {src}: {e}"),
63	    }
64	
65	    println!("cargo:rustc-env={env_var}={}", so_path.display());
66	    println!("cargo:rerun-if-changed={src}");
67	}
