1	//! Regression coverage for the keygen file-permission contract on Unix.
2	//!
3	//! What is protected here (see README "文件权限"):
4	//!
5	//! * Under umask 0022 / 0000 / 0777 a key is generated successfully only as
6	//!   exactly 32 raw bytes with final mode exactly 0600 -- owner read+write,
7	//!   no group/other bits, no extra bits; 0400/0200/0000 are not success.
8	//! * The file is never group/other-accessible, not even for an instant: the
9	//!   mode observed right after creation already carries no group/other bits.
10	//! * Permissions are both set to and *confirmed* as exactly 0600 before any
11	//!   key byte is written. This cannot be observed from the final file, so a
12	//!   small LD_PRELOAD shim (tests/support/permfail) traces the program's
13	//!   open/fchmod/fstat/write calls from inside the process.
14	//! * If the filesystem rejects the required mode (fchmod fails) or the mode
15	//!   cannot be confirmed (fstat fails or reports something other than 0600),
16	//!   keygen exits 1, reports the permission problem on stderr, prints no
17	//!   success message, writes no key bytes, and removes the partial file --
18	//!   without touching pre-existing files, directories, symlinks, or the
19	//!   parent directory. If the system also refuses to remove this run's
20	//!   file, stderr keeps the permission problem, reports the failed cleanup,
21	//!   and warns that this run's file may still be present at the target.
22	//! * Existing CLI behaviour (--version, usage/exit code 2) is unchanged.
23	#![cfg(unix)]
24	
25	use std::collections::HashMap;
26	use std::fs;
27	use std::os::unix::fs::{MetadataExt, PermissionsExt};
28	use std::path::{Path, PathBuf};
29	use std::process::Command;
30	use std::sync::atomic::{AtomicU64, Ordering};
31	
32	const KEY_LEN: usize = 32;
33	const MODE_0600: u32 = 0o600;
34	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
35	
36	fn bin() -> PathBuf {
37	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
38	}
39	
40	fn permfail_so() -> Option<PathBuf> {
41	    option_env!("WRAPFILE_PERMFAIL_SO").map(PathBuf::from)
42	}
43	
44	// ---------------------------------------------------------------------------
45	// scratch directory
46	// ---------------------------------------------------------------------------
47	
48	struct Tmp {
49	    path: PathBuf,
50	}
51	
52	impl Tmp {
53	    fn new(label: &str) -> Tmp {
54	        static SEQ: AtomicU64 = AtomicU64::new(0);
55	        let path = std::env::temp_dir().join(format!(
56	            "wrapfile-keygen-tests-{}-{}-{}",
57	            std::process::id(),
58	            label,
59	            SEQ.fetch_add(1, Ordering::Relaxed)
60	        ));
61	        fs::create_dir_all(&path).unwrap();
62	        // Don't let the harness process's own (possibly strict) umask decide
63	        // the scratch dir's mode: keygen needs a writable parent, and every
64	        // test sets the umask it cares about inside the child shell.
65	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
66	        Tmp { path }
67	    }
68	
69	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
70	        self.path.join(name)
71	    }
72	}
73	
74	impl Drop for Tmp {
75	    fn drop(&mut self) {
76	        // A read-only-parent test may have stripped write permission;
77	        // restore it so teardown can remove the tree.
78	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
79	        let _ = fs::remove_dir_all(&self.path);
80	    }
81	}
82	
83	// ---------------------------------------------------------------------------
84	// running the binary
85	// ---------------------------------------------------------------------------
86	
87	struct Run {
88	    rc: i32,
89	    out: Vec<u8>,
90	    err: Vec<u8>,
91	}
92	
93	fn run_version() -> Run {
94	    let o = Command::new(bin()).arg("--version").output().unwrap();
95	    Run {
96	        rc: o.status.code().unwrap_or(-1),
97	        out: o.stdout,
98	        err: o.stderr,
99	    }
100	}
101	
102	fn run_args(args: &[&str]) -> Run {
103	    let o = Command::new(bin()).args(args).output().unwrap();
104	    Run {
105	        rc: o.status.code().unwrap_or(-1),
106	        out: o.stdout,
107	        err: o.stderr,
108	    }
109	}
110	
111	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
112	/// wrapper (`umask MMMM; exec "$@"`), optionally with the permfail shim
113	/// preloaded and a trace file configured.
114	fn run_keygen(
115	    key: &Path,
116	    umask: u32,
117	    preload_so: Option<&Path>,
118	    extra_env: &[(&str, &str)],
119	    trace_file: Option<&Path>,
120	) -> Run {
121	    let mut cmd = Command::new("/bin/sh");
122	    cmd.arg("-c")
123	        .arg(format!("umask {umask:04o}; exec \"$@\""))
124	        .arg("sh")
125	        .arg(bin())
126	        .arg("keygen")
127	        .arg(key);
128	
129	    if let Some(so) = preload_so {
130	        cmd.env("LD_PRELOAD", so);
131	    }
132	    for (k, v) in extra_env {
133	        cmd.env(k, v);
134	    }
135	    if let Some(t) = trace_file {
136	        cmd.env("WRAPFILE_TEST_TRACE_FILE", t);
137	    }
138	
139	    let o = cmd.output().unwrap();
140	    Run {
141	        rc: o.status.code().unwrap_or(-1),
142	        out: o.stdout,
143	        err: o.stderr,
144	    }
145	}
146	
147	// ---------------------------------------------------------------------------
148	// shim trace log
149	// ---------------------------------------------------------------------------
150	
151	struct Event {
152	    kind: String,
153	    attrs: HashMap<String, String>,
154	    index: usize,
155	}
156	
157	impl Event {
158	    fn get(&self, key: &str) -> Option<&str> {
159	        self.attrs.get(key).map(String::as_str)
160	    }
161	
162	    fn mode(&self) -> Option<u32> {
163	        self.get("mode").and_then(|v| u32::from_str_radix(v, 8).ok())
164	    }
165	
166	    fn size(&self) -> Option<u64> {
167	        self.get("size").and_then(|v| v.parse().ok())
168	    }
169	
170	    fn ret(&self) -> Option<i32> {
171	        self.get("ret").and_then(|v| v.parse().ok())
172	    }
173	}
174	
175	fn parse_trace(path: &Path) -> Vec<Event> {
176	    let text = fs::read_to_string(path).unwrap();
177	    text.lines()
178	        .enumerate()
179	        .map(|(index, line)| {
180	            let mut it = line.split_whitespace();
181	            let kind = it.next().unwrap_or("").to_string();
182	            let attrs = it
183	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
184	                .collect();
185	            Event { kind, attrs, index }
186	        })
187	        .collect()
188	}
189	
190	fn first_index(events: &[Event], pred: impl Fn(&Event) -> bool) -> Option<usize> {
191	    events.iter().position(pred)
192	}
193	
194	/// Create the trace file up front (mode 0644) so that it stays readable even
195	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
196	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
197	    let p = dir.join(name);
198	    fs::File::create(&p).unwrap();
199	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
200	    p
201	}
202	
203	// ---------------------------------------------------------------------------
204	// filesystem assertions
205	// ---------------------------------------------------------------------------
206	
207	fn mode_of(path: &Path) -> u32 {
208	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
209	}
210	
211	fn assert_key_file_ok(path: &Path, run: &Run) -> Vec<u8> {
212	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
213	    assert!(run.err.is_empty(), "unexpected stderr: {}", String::from_utf8_lossy(&run.err));
214	
215	    let meta = fs::metadata(path).expect("key file should exist on success");
216	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
217	
218	    let mode = meta.mode() & 0o7777;
219	    // One assertion that carries the whole contract: exactly 0600 -- owner
220	    // r+w both present, all group/other bits off, no setuid/setgid/sticky.
221	    assert_eq!(
222	        mode, MODE_0600,
223	        "key file mode must be exactly 0600 (owner rw only), got {mode:04o}"
224	    );
225	
226	    let expected_stdout =
227	        format!("Key saved to {}\n", path.display()).into_bytes();
228	    assert_eq!(run.out, expected_stdout, "stdout should only announce the save location");
229	
230	    let bytes = fs::read(path).unwrap();
231	    assert_eq!(bytes.len(), KEY_LEN);
232	    assert!(
233	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
234	        "key bytes must never appear on stdout/stderr"
235	    );
236	    bytes
237	}
238	
239	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
240	    needle.is_empty()
241	        || haystack
242	            .windows(needle.len())
243	            .any(|w| w == needle)
244	}
245	
246	fn assert_permission_failure_cleaned(path: &Path, run: &Run, dir: &Path, allowed_entries: &[&str]) {
247	    assert_eq!(run.rc, 1, "permission problems must fail with exit code 1");
248	    assert!(run.out.is_empty(), "no success message on failure, got {}", String::from_utf8_lossy(&run.out));
249	    assert!(!run.err.is_empty(), "stderr must explain the failure");
250	    let stderr = String::from_utf8_lossy(&run.err);
251	    assert!(
252	        stderr.contains("0600") || stderr.to_lowercase().contains("permission"),
253	        "stderr must describe the permission problem, got: {stderr}"
254	    );
255	    assert!(!path.exists(), "the failed generation's target must be removed");
256	
257	    // Nothing else left behind in the parent directory.
258	    let mut leftovers: Vec<String> = fs::read_dir(dir)
259	        .unwrap()
260	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
261	        .filter(|n| !allowed_entries.contains(&n.as_str()))
262	        .collect();
263	    leftovers.sort();
264	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
265	}
266	
267	// A pre-existing object that must survive a failed keygen byte-for-byte.
268	struct Sentinel {
269	    path: PathBuf,
270	    bytes: Vec<u8>,
271	    mode: u32,
272	    inode: u64,
273	}
274	
275	impl Sentinel {
276	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
277	        let path = dir.join(name);
278	        fs::write(&path, bytes).unwrap();
279	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
280	        let meta = fs::metadata(&path).unwrap();
281	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
282	    }
283	
284	    fn assert_untouched(&self) {
285	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
286	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
287	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
288	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
289	    }
290	}
