347	        let first_write = first_index(&events, |e| e.kind == "FIRST_WRITE")
348	            .expect("the key must eventually be written");
349	        let w = &events[first_write];
350	
351	        // Immediately before the first write call: mode is exactly 0600 and
352	        // size is still 0 -- no key byte preceded the confirmation.
353	        assert_eq!(w.mode().unwrap(), MODE_0600,
354	            "mode at first write must be exactly 0600 (umask {umask:04o})");
355	        assert_eq!(w.size().unwrap(), 0,
356	            "file must be empty when 0600 is confirmed (umask {umask:04o})");
