597	
598	    // The filesystem refuses to set the required mode, and the system then
599	    // refuses to remove this run's (empty) file. The command must report
600	    // both the permission problem and the unfinished cleanup.
601	    let run = run_keygen(
602	        &key,
603	        0o022,
