617	        "the fchmod failure must have been injected"
618	    );
619	    assert!(
620	        events
621	            .iter()
622	            .any(|e| e.kind == "UNLINK" && e.get("errno") == Some("EACCES")),
623	        "the refused cleanup must have been injected"
624	    );
